contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 burnAmount) public payable {
        require(burnAmount > 0);

        uint256 beforeTotalDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(burnAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 afterTotalDistributed = c.totalDistributed(); if (__ESBMC_reverted()) return;

        assert(reverted || afterTotalDistributed + burnAmount == beforeTotalDistributed);
    }

    receive() external payable {}
}

