    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
    }

    function _run(uint256 burnAmount) internal {
        vm.assume(burnAmount > 0);
        uint256 beforeTotalDistributed;
        try c.totalDistributed() returns (uint256 __r) { beforeTotalDistributed = __r; } catch { return; }
        bool reverted;
        try c.burn(burnAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 afterTotalDistributed;
        try c.totalDistributed() returns (uint256 __r) { afterTotalDistributed = __r; } catch { return; }
        assertTrue(reverted || afterTotalDistributed + burnAmount == beforeTotalDistributed);
    }

    function testFuzz_run(uint256 burnAmount) public {
        _run(burnAmount);
    }

